package com.aoo.bcg.common.lifecycle;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ManagedAsyncExecutorTest{@Test void propagatesContextReportsFailureClearsThreadLocalAndShutsDown()throws Exception{var failures=new ArrayList<Throwable>();var managed=new ManagedAsyncExecutor(Executors.newSingleThreadExecutor(Thread.ofPlatform().name("managed-test").factory()),Duration.ofSeconds(1),failures::add);var context=new CompletableFuture<Map<String,String>>();managed.submit(Map.of("traceId","t1"),()->context.complete(ManagedAsyncExecutor.currentContext())).get();assertEquals("t1",context.get().get("traceId"));var cleared=new CompletableFuture<Map<String,String>>();managed.submit(Map.of(),()->cleared.complete(ManagedAsyncExecutor.currentContext())).get();assertTrue(cleared.get().isEmpty());var failed=managed.submit(Map.of(),()->{throw new IllegalStateException("boom");});assertThrows(ExecutionException.class,failed::get);assertEquals(1,failures.size());managed.close();}}
